-- | Gondolin provider (upstream @test_gondolin_environment.py@).
--
-- The provider drives the verbatim embedded @gondolin_sidecar.mjs@ under
-- Node against the verbatim upstream fake SDK
-- (@test/fixtures/fake_gondolin.mjs@, regenerated by
-- @generate_fake_gondolin.py@).  Real Gondolin runs only when
-- @PETRUS_REAL_GONDOLIN_SDK_MODULE@ and @PETRUS_REAL_GONDOLIN_IMAGE@ are
-- set.  Every sidecar a test starts is destroyed through the provider (or
-- killed by its exact recorded PID when the test is about sidecar death).
module GondolinSpec (spec) where

import Control.Concurrent (forkIO, myThreadId, threadDelay)
import Control.Concurrent.MVar
import Control.Exception (SomeException, bracket, finally, throwIO, try)
import Control.Monad (forM_, unless, void, when)
import Data.Bits ((.&.))
import Data.ByteString qualified as B
import Data.ByteString.Char8 qualified as BC
import Data.IORef
import Data.List (isPrefixOf)
import Data.Map.Strict qualified as Map
import Data.Maybe (fromMaybe, isNothing)
import Data.Set qualified as Set
import Data.Text (Text)
import Data.Text qualified as T
import Data.Text.Encoding qualified as TE
import GHC.Clock (getMonotonicTime)
import Network.Socket (Family (AF_UNIX), SockAddr (SockAddrUnix), SocketType (Stream), close, connect, defaultProtocol, socket)
import Network.Socket.ByteString (recv, sendAll)
import Petrus.Json (Json (..), lookupMember)
import Petrus.Motus.Execution
import Petrus.Motus.Execution.Archive (extractWorkspaceArchive, workspaceArchive)
import Petrus.Motus.Execution.Providers.Gondolin
import Support
import System.Directory (createDirectory, createDirectoryIfMissing, doesDirectoryExist, doesFileExist, doesPathExist, findExecutable, listDirectory, makeAbsolute, removeDirectoryRecursive)
import System.Environment (lookupEnv, setEnv, unsetEnv)
import System.Exit (ExitCode (..))
import System.FilePath ((</>))
import System.IO.Temp (withSystemTempDirectory)
import System.Posix.Files (fileMode, getFileStatus)
import System.Posix.Process (getProcessGroupID, getProcessStatus)
import System.Posix.Signals (sigKILL, sigTERM, signalProcess)
import System.Process (CreateProcess (..), StdStream (..), proc, readProcessWithExitCode, withCreateProcess)
import System.Timeout (timeout)
import Test.Hspec

rightOr :: (Show e) => Either e a -> a
rightOr = either (error . show) id

cmd :: [Text] -> Command
cmd argv = rightOr (mkCommand (commandSpec argv))

cmdWith :: [Text] -> (CommandSpec -> CommandSpec) -> Command
cmdWith argv f = rightOr (mkCommand (f (commandSpec argv)))

imageSpec :: Text -> [Capability] -> EnvironmentSpec
imageSpec image capabilities = rightOr (mkEnvironmentSpec (Just image) capabilities)

privateSpec :: Text -> EnvironmentSpec
privateSpec image = imageSpec image [capPrivateFileTransfer]

fakeSdkPath :: IO Text
fakeSdkPath = T.pack <$> makeAbsolute "test/fixtures/fake_gondolin.mjs"

-- | Upstream's @GondolinEnvironment(root, sdk_module=fake, lease_ttl=30)@.
fakeConfig :: Text -> GondolinConfig
fakeConfig sdk = (gondolinConfig sdk) {gondolinLeaseTtl = 30}

newEnv :: FilePath -> GondolinConfig -> IO (GondolinEnvironment, EnvironmentProvider)
newEnv root config = do
  env <- newGondolinEnvironment root config
  pure (env, gondolinProvider env)

attachDigest :: EnvironmentProvider -> EnvironmentLease -> B.ByteString -> IO ExecutionAttachment
attachDigest provider lease archive = providerAttach provider lease archive "digest"

transfer :: EnvironmentProvider -> PrivateFileTransfer
transfer provider = fromMaybe (error "Gondolin offers private-file transfer") (providerPrivateFiles provider)

emptyArchive :: FilePath -> IO B.ByteString
emptyArchive tmp = do
  let source = tmp </> "empty"
  createDirectoryIfMissing True source
  workspaceArchive source

registryOf :: GondolinEnvironment -> Text -> IO Registry
registryOf env operation = fromMaybe (error "registry missing") <$> readRegistry (operationDirectory env operation)

isEmptyDirectory :: FilePath -> IO Bool
isEmptyDirectory path = null <$> listDirectory path

runtimeDirectories :: IO (Set.Set FilePath)
runtimeDirectories = Set.fromList . filter ("petrus-g-" `isPrefixOf`) <$> listDirectory "/tmp"

modeOf :: FilePath -> IO Int
modeOf path = (\s -> fromIntegral (fileMode s .&. 0o7777)) <$> getFileStatus path

-- | Run in a background thread; the result is read with 'joinWithin'.
background :: IO a -> IO (MVar (Either SomeException a))
background action = do
  box <- newEmptyMVar
  _ <- forkIO (try action >>= putMVar box)
  pure box

joinWithin :: Double -> MVar (Either SomeException a) -> IO a
joinWithin seconds box =
  timeout (round (seconds * 1000000)) (readMVar box) >>= \case
    Nothing -> fail "background action did not finish in time"
    Just (Left failure) -> throwIO failure
    Just (Right value) -> pure value

-- | Poll @provider._request(record, {"action": "status"})["active"]@.
awaitActive :: GondolinEnvironment -> Registry -> IO ()
awaitActive env record = do
  deadline <- (+ 1) <$> getMonotonicTime
  let loop = do
        status <- sidecarRequest env record [("action", String "status")] 2
        now <- getMonotonicTime
        unless (lookupMember "active" status == Just (Bool True) || now >= deadline) (threadDelay 10000 >> loop)
  loop

-- | Poll until the lease is no longer READY (or the deadline passes).
awaitNotReady :: GondolinEnvironment -> Text -> Double -> Double -> IO ()
awaitNotReady env operation seconds step = do
  deadline <- (+ seconds) <$> getMonotonicTime
  let loop = do
        lease <- gondolinLookup env operation
        now <- getMonotonicTime
        when (fmap leaseState lease == Just Ready && now < deadline) (threadDelay (round (step * 1000000)) >> loop)
  loop

lookupState :: GondolinEnvironment -> Text -> IO (Maybe LeaseState)
lookupState env operation = fmap leaseState <$> gondolinLookup env operation

-- | Kill a sidecar this test started, by its exact recorded PID, and reap it.
killSidecar :: Registry -> IO ()
killSidecar record = do
  signalProcess sigKILL (fromIntegral (registryPid record))
  void (getProcessStatus True False (fromIntegral (registryPid record)))

withEnvironment :: [(String, Maybe String)] -> IO a -> IO a
withEnvironment assignments action = do
  saved <- mapM (\(k, _) -> (k,) <$> lookupEnv k) assignments
  let apply = mapM_ (\(k, v) -> maybe (unsetEnv k) (setEnv k) v)
  bracket (apply assignments) (const (apply saved)) (const action)

-- | A registry record for the process-group unit tests.
unitRecord :: Text -> Identity -> Maybe [(Text, Text)] -> Registry
unitRecord runtime start groups =
  Registry
    { registryOperationId = "unit"
    , registryLeaseId = "lease"
    , registrySpecFingerprint = "fingerprint"
    , registryBootToken = "token"
    , registryPid = 41
    , registryPgid = 41
    , registryStartIdentity = start
    , registrySocket = "/tmp/unit-socket"
    , registryRuntime = runtime
    , registryWorkspace = "/tmp/unit-workspace"
    , registrySdkModule = "sdk"
    , registrySdkVersion = gondolinVersion
    , registryImage = "image"
    , registryGroupIdentities = Map.fromList <$> groups
    , registryPrivateFileTransfer = False
    }

present :: Text -> Identity
present marker = Identity "present" (Just marker) Nothing

missing :: Identity
missing = Identity "missing" Nothing Nothing

-- | An inspector whose group listings come from a script (then @[]@),
-- recording every signal instead of sending it.
scriptedInspector :: [[GroupMember]] -> Bool -> (Int -> Identity) -> IO (ProcessInspector, IORef [(Int, Int)])
scriptedInspector script repeatLast identity = do
  remaining <- newIORef script
  signalled <- newIORef []
  let members _ =
        atomicModifyIORef' remaining $ \case
          [] -> ([], [])
          [lastOne] | repeatLast -> ([lastOne], lastOne)
          next : rest -> (rest, next)
      kill pgid signal = do
        modifyIORef' signalled (<> [(pgid, fromIntegral signal)])
        pure True
  pure (ProcessInspector members (pure . identity) kill, signalled)

spec :: Spec
spec = describe "Gondolin provider" $ do
  node <- runIO (findExecutable "node")
  sdk <- runIO fakeSdkPath

  describe "embedded sidecar" $ do
    it "is the verbatim upstream sidecar (pinned SHA-256)" $ do
      sidecarSha256 `shouldBe` "498cffb83fb6245670e1bb5f7231374262e60cc2cfe86d20746a700eaad19b44"
      onDisk <- B.readFile "data/gondolin_sidecar.mjs"
      onDisk `shouldBe` sidecarSource
      -- The pinned submodule is required: a missing checkout fails here
      -- rather than skipping the comparison.
      B.readFile "../../upstream/petrus/src/petrus/motus/_execution/gondolin_sidecar.mjs" `shouldReturn` sidecarSource

    it "has valid Node syntax (test_sidecar_has_valid_node_syntax)" $ case node of
      Nothing -> expectationFailure "node is not on PATH: this example checks the sidecar with the real Node"
      Just executable -> withTempDir $ \tmp -> do
        let path = tmp </> "gondolin_sidecar.mjs"
        B.writeFile path sidecarSource
        (code, _, err) <- readProcessWithExitCode executable ["--check", path] ""
        (code, err) `shouldBe` (ExitSuccess, "")

  describe "constructor and contract" $ do
    it "validates TTL, startup timeout and SDK module" $ withTempDir $ \tmp -> do
      newGondolinEnvironment (tmp </> "a") ((gondolinConfig "sdk.mjs") {gondolinLeaseTtl = 0})
        `shouldThrowMessage` (ValueError, "Gondolin lease TTL must be positive")
      newGondolinEnvironment (tmp </> "b") ((gondolinConfig "sdk.mjs") {gondolinStartupTimeout = 0})
        `shouldThrowMessage` (ValueError, "Gondolin startup timeout must be positive")
      newGondolinEnvironment (tmp </> "c") (gondolinConfig "")
        `shouldThrowMessage` (ValueError, "Gondolin requires an explicit SDK module URL or path")
      _ <- newGondolinEnvironment (tmp </> "d" </> "nested") (gondolinConfig "sdk.mjs")
      modeOf (tmp </> "d" </> "nested") `shouldReturn` 0o700

    it "discovers the Gondolin capabilities and private-file transfer (capability discovery) (test_provider_capability_discovery_is_semantic_and_provider_differences_are_explicit[gondolin])" $ withTempDir $ \tmp -> do
      (_, provider) <- newEnv (tmp </> "gondolin") (gondolinConfig "unused.mjs")
      providerName provider `shouldBe` "gondolin"
      providerCapabilities provider
        `shouldBe` Set.fromList [capExplicitEnvironment, capMicrovm, capPrivateFileTransfer, capRecreatableLookup, capTerritoryCancellation, capVm, capWorkspace]
      isNothing (providerPrivateFiles provider) `shouldBe` False

    it "never verifies absence for a foreign provider (destroy foreign) (test_destroy_never_verifies_absence_for_a_foreign_provider[gondolin])" $ withTempDir $ \tmp -> do
      (_, provider) <- newEnv (tmp </> "gondolin") (gondolinConfig "unused.mjs")
      let foreignLease = rightOr (mkEnvironmentLease "foreign-cleanup" "foreign-provider" "foreign-lease" Set.empty Ready)
      result <- providerDestroy provider foreignLease
      cleanupDisposition result `shouldBe` Unverified
      cleanupVerified result `shouldBe` False

    it "rejects unsafe operation ids and missing images" $ withTempDir $ \tmp -> do
      (env, provider) <- newEnv (tmp </> "g") (gondolinConfig "unused.mjs")
      gondolinLookup env "bad/op" `shouldThrowMessage` (ValueError, "operation id must be a safe non-empty provider label")
      gondolinLookup env (T.replicate 129 "a") `shouldThrowMessage` (ValueError, "operation id must be a safe non-empty provider label")
      gondolinLookup env "-leading.ok_" `shouldReturn` Nothing
      providerCreate provider "op" defaultSpec `shouldThrowMessage` (ValueError, "Gondolin requires an image")
      providerCreate provider "op" (imageSpec "x" [capContainer])
        `shouldThrowMessage` (ValueError, "unsupported capabilities: ['container']")
      providerReconcile provider "op" >>= \r -> reconcileClassification r `shouldBe` ReconcileRetryable

  describe "process-group identity" $ do
    it "uses ps when /proc is unavailable (test_process_identity_uses_ps_when_proc_is_unavailable)" $ do
      let expected = Identity "present" (Just "start") (Just "node sidecar")
      processIdentityWith (pure False) (const (pure expected)) 41 `shouldReturn` expected

    it "reads this process's identity" $ do
      identity <- processIdentity 1
      identityState identity `shouldSatisfy` (`elem` ["present", "uninspectable"])

    it "ignores a member that exited after enumeration (group identity snapshot) (test_group_identity_snapshot_ignores_member_that_exited_after_enumeration)" $ do
      (processes, _) <-
        scriptedInspector
          [[GroupMember 41 "node sidecar", GroupMember 99 "finished-helper"]]
          True
          (\pid -> if pid == 41 then present "leader-start" else missing)
      groupIdentities processes (unitRecord "/tmp/petrus-g-x" (present "leader-start") Nothing)
        `shouldReturn` Map.fromList [("41", "leader-start")]

    it "fails closed on a foreign reused process group without signalling (test_foreign_reused_process_group_fails_closed_without_signal)" $ do
      (processes, signalled) <- scriptedInspector [[GroupMember 99 "unrelated"]] True (const missing)
      errorMatching
        (cleanupGroup processes (unitRecord "/private/token" (Identity "present" Nothing Nothing) Nothing))
        RuntimeError
        "uncertain"
      readIORef signalled `shouldReturn` []

    it "allows zombie-leader cleanup with the same process marker (test_same_process_marker_allows_zombie_leader_cleanup)" $ do
      (processes, signalled) <-
        scriptedInspector [[GroupMember 41 "<defunct>"], []] False (const (Identity "present" (Just "boot:100") (Just "")))
      cleanupGroup processes (unitRecord "/tmp/petrus-g-token" (Identity "present" (Just "boot:100") (Just "node sidecar")) Nothing)
      readIORef signalled `shouldReturn` [(41, fromIntegral sigTERM)]

    it "allows orphan process-group cleanup by recorded member identity (test_recorded_member_identity_allows_orphan_process_group_cleanup)" $ do
      (processes, signalled) <-
        scriptedInspector
          [[GroupMember 99 "qemu-system-aarch64"], []]
          False
          (\pid -> if pid == 99 then present "member-start" else missing)
      cleanupGroup processes (unitRecord "/tmp/petrus-g-token" (present "leader-start") (Just [("41", "leader-start"), ("99", "member-start")]))
      readIORef signalled `shouldReturn` [(41, fromIntegral sigTERM)]

    it "fails closed without signalling when a recorded member identity changed (test_changed_recorded_member_identity_fails_closed_without_signal)" $ do
      (processes, signalled) <-
        scriptedInspector
          [[GroupMember 99 "qemu-system-aarch64"]]
          True
          (\pid -> if pid == 99 then present "reused-member" else missing)
      errorMatching
        (cleanupGroup processes (unitRecord "/tmp/petrus-g-token" (present "leader-start") (Just [("41", "leader-start"), ("99", "original-member")])))
        RuntimeError
        "uncertain"
      readIORef signalled `shouldReturn` []

    -- @ps -axo@ lists every process on the host, so one command line that is
    -- not UTF-8 (a shell whose argument holds byte 0xFF, waiting on stdin) must
    -- not fail the group snapshot or an identity: if it did, every create
    -- and destroy would fail for as long as that process ran.
    it "reads the process table while a command line is not UTF-8" $
      withCreateProcess (proc "/bin/sh" ["-c", "exec /bin/sh -c 'read line' \"$(printf 'petrus-\\377')\""]) {std_in = CreatePipe} $ \_ _ _ _ -> do
        group <- fromIntegral <$> getProcessGroupID
        deadline <- (+ 5) <$> getMonotonicTime
        let named = filter (("petrus-\xFFFD" `T.isInfixOf`) . memberCommand)
            await = do
              members <- groupMembers group
              now <- getMonotonicTime
              if null (named members) && now < deadline then threadDelay 20000 >> await else pure members
        members <- await
        case named members of
          member : _ -> do
            identity <- psIdentity (memberPid member)
            identityState identity `shouldBe` "present"
            fmap ("petrus-\xFFFD" `T.isInfixOf`) (identityCommand identity) `shouldBe` Just True
          [] -> expectationFailure ("no group member names the undecodable argument: " <> show members)

    it "escalates TERM then KILL while members remain" $ do
      (processes, signalled) <-
        scriptedInspector [[GroupMember 41 "/tmp/petrus-g-token/s"]] True (const missing)
      cleanupGroup processes (unitRecord "/tmp/petrus-g-token" missing Nothing)
      readIORef signalled `shouldReturn` [(41, fromIntegral sigTERM), (41, fromIntegral sigKILL)]

  case node of
    Nothing -> it "fake-SDK lifecycle" (expectationFailure "node is not on PATH: the fake-SDK lifecycle runs the sidecar under the real Node")
    Just _ -> fakeSuite sdk

  realSuite

fakeSuite :: Text -> Spec
fakeSuite sdk = describe "against the verbatim sidecar and fake SDK" $ do
  it "runs the lifecycle with recreation, VFS and bounds (test_gondolin_sidecar_lifecycle_recreation_vfs_and_bounds)" $
    withTempDir $ \tmp -> withEnvironment [("GITHUB_TOKEN", Just "host-secret")] $ do
      let root = tmp </> "short"
      (env, provider) <- newEnv root (fakeConfig sdk)
      lease <- provision env "operation" (imageSpec "fake-image" [capVm, capMicrovm])
      cleanupBox <- newIORef Nothing
      ( do
          leaseState lease `shouldBe` Ready
          record <- registryOf env "operation"
          identity <- processIdentity (registryPid record)
          fromMaybe "" (identityCommand identity) `shouldNotSatisfy` T.isInfixOf (registryBootToken record)
          modeOf (operationDirectory env "operation" </> "registry.json") `shouldReturn` 0o600
          modeOf (T.unpack (registrySocket record)) `shouldReturn` 0o600
          doesFileExist (T.unpack (registryRuntime record) </> "sessions" </> "fake-session.json") `shouldReturn` True
          B.length (TE.encodeUtf8 (registrySocket record)) `shouldSatisfy` (< 100)
          bracket (socket AF_UNIX Stream defaultProtocol) close $ \client -> do
            connect client (SockAddrUnix (T.unpack (registrySocket record)))
            sendAll client "{\"action\":\"handshake\",\"lease_id\":\"wrong\",\"boot_token\":\"wrong\"}\n"
            reply <- recv client 1024
            reply `shouldSatisfy` B.isInfixOf "\"authentication failed\""
          (recreated, _) <- newEnv root (gondolinConfig sdk)
          gondolinLookup recreated "operation" `shouldReturn` Just lease
          errorMatching (provision env "operation" (imageSpec "other" [])) ValueError "collides"
          let source = tmp </> "source"
          createDirectory source
          writeFile (source </> "input") "host"
          attachment <- attachDigest provider lease =<< workspaceArchive source
          attachmentWorkspace attachment `shouldBe` "/workspace"
          result <-
            providerExecute provider attachment $
              cmdWith
                [ "/bin/sh"
                , "-c"
                , "cat input; printf %s \"${GITHUB_TOKEN-unset}\" > output; printf \"#!/bin/sh\\n\" > mode.sh; chmod 755 mode.sh"
                ]
                (\s -> s {specEnvironment = [("ALLOWED", "yes")]})
          (resultReturncode result, resultStdout result) `shouldBe` (0, "host")
          let restored = tmp </> "restored"
          exported <- providerExport provider attachment
          extractWorkspaceArchive exported restored
          readFile (restored </> "output") `shouldReturn` "unset"
          modeOf (restored </> "mode.sh") `shouldReturn` 0o755
          let stale = rightOr (mkEnvironmentLease "operation" "different-provider" (leaseId lease) (leaseCapabilities lease) (leaseState lease))
          (cleanupDisposition <$> providerDestroy provider stale) `shouldReturn` Unverified
          gondolinLookup env "operation" `shouldReturn` Just lease
        )
        `finally` (providerDestroy provider lease >>= writeIORef cleanupBox . Just)
      Just cleanup <- readIORef cleanupBox
      (cleanupDisposition cleanup, cleanupIdentity cleanup) `shouldBe` (Clean, leaseIdentity lease)
      gondolinLookup env "operation" `shouldReturn` Nothing
      (reconcileClassification <$> providerReconcile provider "operation") `shouldReturn` ReconcileRetryable
      isEmptyDirectory root `shouldReturn` True

  forM_ ["GONDOLIN_IMAGE_STORE", "XDG_CACHE_HOME"] $ \variable ->
    it ("resolves a custom image store from " <> variable <> " before VM creation (test_sidecar_resolves_a_custom_image_store_locally_before_vm_creation[" <> variable <> "])") $ withTempDir $ \tmp -> do
      let store = tmp </> "image-store"
          other = if variable == "GONDOLIN_IMAGE_STORE" then "XDG_CACHE_HOME" else "GONDOLIN_IMAGE_STORE"
      createDirectory store
      withEnvironment [(variable, Just store), (other, Nothing)] $ do
        let root = tmp </> "g"
        (env, provider) <- newEnv root (fakeConfig sdk)
        lease <- providerCreate provider "custom-store" (imageSpec "fake-image-custom-store" [])
        leaseState lease `shouldBe` Ready
        (cleanupVerified <$> providerDestroy provider lease) `shouldReturn` True
        void (pure env)
        isEmptyDirectory root `shouldReturn` True

  it "sanitizes a missing local image store path (test_sidecar_sanitizes_a_missing_local_image_store_path)" $ withTempDir $ \tmp -> do
    let store = tmp </> "private-image-store"
    withEnvironment [("GONDOLIN_IMAGE_STORE", Just store)] $ do
      let root = tmp </> "g"
      (_, provider) <- newEnv root (fakeConfig sdk)
      outcome <- try (providerCreate provider "missing-image" (imageSpec "missing-image" []))
      case outcome of
        Left failure -> do
          errorKind failure `shouldBe` RuntimeError
          errorMessage failure `shouldSatisfy` T.isInfixOf "Gondolin local image is unavailable"
          errorMessage failure `shouldNotSatisfy` T.isInfixOf (T.pack store)
        Right _ -> expectationFailure "expected the missing image to fail"
      isEmptyDirectory root `shouldReturn` True

  it "routes private files and persists the grant (test_gondolin_private_file_route_and_persisted_grant)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (fakeConfig sdk)
    let files = transfer provider
    lease <- providerCreate provider "private" (privateSpec "fake-image")
    ( do
        capPrivateFileTransfer `Set.member` leaseCapabilities lease `shouldBe` True
        (recreated, _) <- newEnv root (gondolinConfig sdk)
        gondolinLookup recreated "private" `shouldReturn` Just lease
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        let canary = "private-canary-never-promoted"
        reference <- importPrivateFile files attachment (rightOr (mkPrivateFile "secret" canary))
        let forged = rightOr (mkPrivateFileRef (refFileId reference) "other" (refAttachmentId reference) (refProvenance reference))
        errorMatching (exportPrivateFile files attachment forged) RuntimeError "private operation failed"
        (privateCleanupDisposition <$> deletePrivateFile files attachment forged) `shouldReturn` Unverified
        errorMatching
          (providerExecute provider attachment (cmdWith ["true"] (\s -> s {specPrivateRoots = [("PRIVATE", forged)]})))
          RuntimeError
          "private reference unavailable"
        result <-
          providerExecute provider attachment $
            cmdWith ["/bin/sh", "-c", "printf after > \"$PRIVATE/secret\""] (\s -> s {specPrivateRoots = [("PRIVATE", reference)]})
        resultReturncode result `shouldBe` 0
        exportPrivateFile files attachment reference `shouldReturn` rightOr (mkPrivateFile "secret" "after")
        exported <- providerExport provider attachment
        (resultStdout result <> resultStderr result <> exported) `shouldNotSatisfy` B.isInfixOf canary
        (privateCleanupRemoved <$> deletePrivateFile files attachment reference) `shouldReturn` 1
        (privateCleanupDisposition <$> deletePrivateFile files attachment reference) `shouldReturn` NotCreated
        (privateCleanupVerified <$> cleanupPrivateFiles files attachment) `shouldReturn` True
        record <- registryOf env "private"
        registryBytes <- B.readFile (operationDirectory env "private" </> "registry.json")
        registryBytes `shouldNotSatisfy` B.isInfixOf canary
        B.readFile (T.unpack (registryRuntime record) </> "stderr") >>= (`shouldNotSatisfy` B.isInfixOf canary)
        let workspace = T.unpack (registryWorkspace record)
        names <- listDirectory workspace
        forM_ names $ \name -> do
          isFile <- doesFileExist (workspace </> name)
          when isFile (B.readFile (workspace </> name) >>= (`shouldNotSatisfy` B.isInfixOf canary))
        BC.pack (show reference <> show result) `shouldNotSatisfy` B.isInfixOf canary
      )
      `finally` (providerDestroy provider lease >>= (`shouldBe` True) . cleanupVerified)

  it "does not grant private transfer without the requirement (test_gondolin_lease_without_requirement_does_not_gain_private_transfer)" $ withTempDir $ \tmp -> do
    (_, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- providerCreate provider "ordinary" (imageSpec "fake-image" [])
    ( do
        capPrivateFileTransfer `Set.member` leaseCapabilities lease `shouldBe` False
        archive <- emptyArchive tmp
        first <- providerAttach provider lease archive "first"
        _ <- providerAttach provider lease archive "second"
        (resultReturncode <$> providerExecute provider first (cmd ["true"])) `shouldReturn` 0
        errorMatching
          (importPrivateFile (transfer provider) first (rightOr (mkPrivateFile "secret" "x")))
          ValueError
          "lease does not grant private-file transfer"
      )
      `finally` void (providerDestroy provider lease)

  it "never lets an existing non-capable lease satisfy a later private requirement (test_existing_noncapable_lease_cannot_satisfy_later_private_requirement)" $ withTempDir $ \tmp -> do
    (_, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- providerCreate provider "fixed-grant" (imageSpec "fake-image" [])
    errorMatching (providerCreate provider "fixed-grant" (privateSpec "fake-image")) RuntimeError "lacks required capabilities"
      `finally` (providerDestroy provider lease >>= (`shouldBe` True) . cleanupVerified)

  it "rolls back a failed private probe without relocking or residue (test_private_probe_failure_rolls_back_without_relocking_or_residue)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    created <- newIORef []
    let hooks =
          noHooks
            { hookRequest = \action -> when (action == "private_probe") (throwExecution RuntimeError "probe detail must not escape")
            , hookRuntimeCreated = \runtime -> modifyIORef' created (runtime :)
            }
    (env, provider) <- newEnv root (fakeConfig sdk) {gondolinHooks = hooks}
    outcome <- try (providerCreate provider "probe-failure" (privateSpec "fake-image"))
    case outcome of
      Left failure -> do
        errorKind failure `shouldBe` RuntimeError
        errorMessage failure `shouldSatisfy` T.isInfixOf "security probe failed"
        errorMessage failure `shouldNotSatisfy` T.isInfixOf "probe detail"
      Right _ -> expectationFailure "expected the probe to fail"
    gondolinLookup env "probe-failure" `shouldReturn` Nothing
    isEmptyDirectory root `shouldReturn` True
    runtimes <- readIORef created
    runtimes `shouldNotBe` []
    mapM doesPathExist runtimes `shouldReturn` map (const False) runtimes

  it "keeps symlink replacement unverified and never touches its target (test_private_symlink_replacement_is_unverified_and_never_touches_target)" $ withTempDir $ \tmp -> do
    (_, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    let files = transfer provider
    lease <- providerCreate provider "private-symlink" (privateSpec "fake-image")
    let source = tmp </> "source-symlink"
    createDirectory source
    B.writeFile (source </> "victim") "victim"
    ( do
        attachment <- attachDigest provider lease =<< workspaceArchive source
        reference <- importPrivateFile files attachment (rightOr (mkPrivateFile "secret" "private"))
        result <-
          providerExecute provider attachment $
            cmdWith
              ["/bin/sh", "-c", "rm \"$PRIVATE/secret\"; ln -s /workspace/victim \"$PRIVATE/secret\""]
              (\s -> s {specPrivateRoots = [("PRIVATE", reference)]})
        resultReturncode result `shouldBe` 0
        errorMatching (exportPrivateFile files attachment reference) RuntimeError "private operation failed"
        (privateCleanupDisposition <$> deletePrivateFile files attachment reference) `shouldReturn` Unverified
        let replacement = tmp </> "replacement-symlink"
        createDirectory replacement
        replacementArchive <- workspaceArchive replacement
        errorMatching (providerAttach provider lease replacementArchive "replacement") RuntimeError "private attachment cleanup failed"
        let restored = tmp </> "restored-symlink"
        exported <- providerExport provider attachment
        extractWorkspaceArchive exported restored
        B.readFile (restored </> "victim") `shouldReturn` "victim"
      )
      `finally` (providerDestroy provider lease >>= (`shouldBe` True) . cleanupVerified)

  it "reports private cleanup as unverified while a command is active (test_private_cleanup_is_unverified_while_command_is_active)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    let files = transfer provider
    lease <- providerCreate provider "private-active" (privateSpec "fake-image")
    ( do
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        reference <- importPrivateFile files attachment (rightOr (mkPrivateFile "secret" "private"))
        running <-
          background . providerExecute provider attachment $
            cmdWith ["/bin/sh", "-c", "sleep 0.4"] (\s -> s {specPrivateRoots = [("PRIVATE", reference)]})
        record <- registryOf env "private-active"
        awaitActive env record
        (privateCleanupDisposition <$> cleanupPrivateFiles files attachment) `shouldReturn` Unverified
        result <- joinWithin 2 running
        resultReturncode result `shouldBe` 0
        (privateCleanupVerified <$> cleanupPrivateFiles files attachment) `shouldReturn` True
      )
      `finally` (providerDestroy provider lease >>= (`shouldBe` True) . cleanupVerified)

  it "requires territory destroy for verified cleanup after private sidecar death (test_private_sidecar_death_requires_territory_destroy_for_verified_cleanup)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    let files = transfer provider
    lease <- providerCreate provider "private-death" (privateSpec "fake-image")
    attachment <- attachDigest provider lease =<< emptyArchive tmp
    _ <- importPrivateFile files attachment (rightOr (mkPrivateFile "secret" "private"))
    record <- registryOf env "private-death"
    killSidecar record
    cleanup <- cleanupPrivateFiles files attachment
    (privateCleanupDisposition cleanup, privateCleanupVerified cleanup) `shouldBe` (Unverified, False)
    (cleanupVerified <$> providerDestroy provider lease) `shouldReturn` True
    doesPathExist (T.unpack (registryRuntime record)) `shouldReturn` False

  it "closes the lease when a command times out (test_gondolin_timeout_destroys_lease)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- provision env "timeout-op" (imageSpec "fake-image" [])
    ( do
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        result <- providerExecute provider attachment (cmdWith ["/bin/sh", "-c", "sleep 10"] (\s -> s {specTimeout = Just 0.05}))
        resultTimedOut result `shouldBe` True
        lookupState env "timeout-op" `shouldReturn` Just Uncertain
      )
      `finally` void (providerDestroy provider lease)

  it "closes on output overflow and destroy is idempotent (test_gondolin_output_overflow_closes_and_destroy_is_idempotent)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (fakeConfig sdk)
    lease <- provision env "overflow" (imageSpec "fake-image" [])
    attachment <- attachDigest provider lease =<< emptyArchive tmp
    result <- providerExecute provider attachment (cmdWith ["/bin/sh", "-c", "printf 12345"] (\s -> s {specOutputLimit = 3}))
    (resultOutputTruncated result, resultStdout result) `shouldBe` (True, "123")
    (cleanupDisposition <$> providerDestroy provider lease) `shouldReturn` Clean
    (cleanupDisposition <$> providerDestroy provider lease) `shouldReturn` NotCreated
    isEmptyDirectory root `shouldReturn` True

  it "keeps the command cwd guest-lexical and inside the workspace (test_command_cwd_is_guest_lexical_and_cannot_escape_workspace)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- provision env "cwd" (imageSpec "fake-image" [])
    ( do
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        (resultReturncode <$> providerExecute provider attachment (cmd ["true"])) `shouldReturn` 0
        errorMatching (providerExecute provider attachment (cmdWith ["true"] (\s -> s {specCwd = "../escape"}))) ValueError "escapes"
      )
      `finally` void (providerDestroy provider lease)

  it "creates one lease and one sidecar under concurrent provision (test_concurrent_provision_creates_one_lease_and_sidecar)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    environments <- mapM (const (newGondolinEnvironment root (fakeConfig sdk))) [1 :: Int, 2]
    boxes <- mapM (\env -> background (provision env "concurrent" (imageSpec "fake-image" []))) environments
    leases <- mapM (joinWithin 30) boxes
    case leases of
      [first, second] -> do
        first `shouldBe` second
        directories <- listDirectory root
        registries <- filter id <$> mapM (\d -> doesFileExist (root </> d </> "registry.json")) directories
        length registries `shouldBe` 1
        void (providerDestroy (gondolinProvider (head' environments)) first)
      _ -> expectationFailure "expected two leases"

  it "removes the runtime and operation directory on spawn failure (test_spawn_failure_removes_runtime_and_operation_directory)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    runtimesBefore <- runtimeDirectories
    (_, provider) <- newEnv root (gondolinConfig sdk) {gondolinNode = "/missing/petrus-node"}
    outcome <- try (providerCreate provider "spawn-failure" (imageSpec "fake-image" []))
    case outcome of
      Left failure -> errorMessage failure `shouldBe` "[Errno 2] No such file or directory: '/missing/petrus-node'"
      Right _ -> expectationFailure "expected FileNotFoundError"
    isEmptyDirectory root `shouldReturn` True
    runtimesAfter <- runtimeDirectories
    runtimesAfter `shouldSatisfy` (`Set.isSubsetOf` runtimesBefore)

  it "stops the unregistered sidecar when the registry write fails (test_registry_write_failure_stops_unregistered_sidecar)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    runtimesBefore <- runtimeDirectories
    let hooks = noHooks {hookWriteRegistry = throwExecution OSError "disk"}
    (_, provider) <- newEnv root (fakeConfig sdk) {gondolinHooks = hooks}
    providerCreate provider "registry-failure" (imageSpec "fake-image" []) `shouldThrowMessage` (OSError, "disk")
    isEmptyDirectory root `shouldReturn` True
    runtimesAfter <- runtimeDirectories
    runtimesAfter `shouldSatisfy` (`Set.isSubsetOf` runtimesBefore)

  it "fails closed on an unregistered workspace before creating a runtime (test_unregistered_workspace_fails_closed_before_runtime_creation)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (fakeConfig sdk)
    createDirectoryIfMissing True (operationDirectory env "orphan" </> "workspace")
    runtimesBefore <- runtimeDirectories
    let orphan = rightOr (mkEnvironmentLease "orphan" "gondolin" "unregistered" gondolinCapabilities Uncertain)
    cleanup <- providerDestroy provider orphan
    (cleanupDisposition cleanup, cleanupVerified cleanup) `shouldBe` (Unverified, False)
    doesDirectoryExist (operationDirectory env "orphan" </> "workspace") `shouldReturn` True
    errorMatching (providerCreate provider "orphan" (imageSpec "fake-image" [])) RuntimeError "uncertain custody"
    runtimesAfter <- runtimeDirectories
    runtimesAfter `shouldSatisfy` (`Set.isSubsetOf` runtimesBefore)

  it "re-validates the lock after destroy unlinks a waiter's inode (test_lock_revalidates_after_destroy_unlinks_a_waiters_inode)" $ withTempDir $ \tmp -> do
    waiter <- newEmptyMVar
    opened <- newEmptyMVar
    let hooks =
          noHooks
            { hookLockOpened = do
                me <- myThreadId
                expected <- tryReadMVar waiter
                when (expected == Just me) (void (tryPutMVar opened ()))
            }
    env <- newGondolinEnvironment (tmp </> "g") (fakeConfig sdk) {gondolinHooks = hooks}
    observed <- newEmptyMVar
    withOperationLock env "race" $ \directory -> do
      go <- newEmptyMVar
      thread <- forkIO $ do
        readMVar go
        withOperationLock env "race" $ \d -> do
          exists <- doesDirectoryExist d
          locked <- doesFileExist (d </> "lock")
          putMVar observed (exists && locked)
      putMVar waiter thread
      putMVar go ()
      timeout 1000000 (readMVar opened) `shouldReturn` Just ()
      threadDelay 50000
      removeDirectoryRecursive directory
    timeout 1000000 (readMVar observed) `shouldReturn` Just True

  it "enforces single-flight commands (test_sidecar_enforces_single_flight_commands)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- provision env "single-flight" (imageSpec "fake-image" [])
    ( do
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        first <- background (providerExecute provider attachment (cmdWith ["/bin/sh", "-c", "sleep 10"] (\s -> s {specTimeout = Just 0.3})))
        record <- registryOf env "single-flight"
        awaitActive env record
        errorMatching (providerExecute provider attachment (cmd ["true"])) RuntimeError "command already active"
        result <- joinWithin 2 first
        resultTimedOut result `shouldBe` True
      )
      `finally` void (providerDestroy provider lease)

  it "closes the active lease when the currency check fails (test_currency_check_failure_closes_active_lease)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- provision env "currency-error" (imageSpec "fake-image" [])
    ( do
        calls <- newIORef (0 :: Int)
        let current = do
              n <- atomicModifyIORef' calls (\c -> (c + 1, c))
              if n == 0 then pure True else throwExecution RuntimeError "currency unavailable"
        attachment <- attachDigest provider lease =<< emptyArchive tmp
        errorMatching
          (providerExecute provider attachment (cmdWith ["/bin/sh", "-c", "sleep 10"] (\s -> s {specIsCurrent = Just current})))
          RuntimeError
          "currency unavailable"
        awaitNotReady env "currency-error" 1 0.01
        lookupState env "currency-error" `shouldReturn` Just Uncertain
      )
      `finally` void (providerDestroy provider lease)

  it "closes a fresh lease on supersession (test_supersession_closes_fresh_lease)" $ withTempDir $ \tmp -> do
    (env, provider) <- newEnv (tmp </> "g") (fakeConfig sdk)
    lease <- provision env "superseded" (imageSpec "fake-image" [])
    checks <- newIORef [True, True, False]
    let current = atomicModifyIORef' checks (\case [] -> ([], False); c : cs -> (cs, c))
    attachment <- attachDigest provider lease =<< emptyArchive tmp
    result <- providerExecute provider attachment (cmdWith ["/bin/sh", "-c", "sleep 10"] (\s -> s {specIsCurrent = Just current}))
    resultSuperseded result `shouldBe` True
    _ <- providerDestroy provider lease
    void (providerDestroy provider lease)

  it "expires by TTL and is destroyed without residue (test_ttl_expires_and_can_be_destroyed_without_residue)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (gondolinConfig sdk) {gondolinLeaseTtl = 0.1}
    lease <- provision env "ttl" (imageSpec "fake-image" [])
    awaitNotReady env "ttl" 3 0.03
    lookupState env "ttl" `shouldReturn` Just Uncertain
    _ <- providerDestroy provider lease
    isEmptyDirectory root `shouldReturn` True

  it "gives the private security probe startup grace before a short TTL (test_private_security_probe_gets_startup_grace_before_short_ttl)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (gondolinConfig sdk) {gondolinLeaseTtl = 0.05}
    lease <- providerCreate provider "private-ttl" (privateSpec "fake-image-slow-probe")
    leaseState lease `shouldBe` Ready
    awaitNotReady env "private-ttl" 3 0.01
    lookupState env "private-ttl" `shouldReturn` Just Uncertain
    (cleanupVerified <$> providerDestroy provider lease) `shouldReturn` True
    isEmptyDirectory root `shouldReturn` True

  it "verifies cleanup after hard sidecar death (test_hard_sidecar_death_has_verified_cleanup)" $ withTempDir $ \tmp -> do
    let root = tmp </> "g"
    (env, provider) <- newEnv root (fakeConfig sdk)
    lease <- provision env "hard-death" (imageSpec "fake-image" [])
    record <- registryOf env "hard-death"
    let sessions = T.unpack (registryRuntime record) </> "sessions"
    doesDirectoryExist sessions `shouldReturn` True
    killSidecar record
    (cleanupVerified <$> providerDestroy provider lease) `shouldReturn` True
    doesPathExist sessions `shouldReturn` False
    doesPathExist (T.unpack (registrySocket record)) `shouldReturn` False
    isEmptyDirectory root `shouldReturn` True
  where
    head' = \case
      x : _ -> x
      [] -> error "empty"

-- | @test_real_gondolin_lifecycle_is_explicitly_opt_in@.
realSuite :: Spec
realSuite = do
  sdkModule <- runIO (lookupEnv "PETRUS_REAL_GONDOLIN_SDK_MODULE")
  image <- runIO (lookupEnv "PETRUS_REAL_GONDOLIN_IMAGE")
  -- The real SDK needs Node >= 23.6 (the sidecar refuses older runtimes);
  -- upstream takes @node@ from PATH, this optional knob names it directly.
  node <- runIO (fromMaybe "node" <$> lookupEnv "PETRUS_REAL_GONDOLIN_NODE")
  describe "against real Gondolin" $ case (sdkModule, image) of
    (Just sdkText, Just imageText) | not (null sdkText) && not (null imageText) ->
      it "runs the real lifecycle (opt-in) (test_real_gondolin_lifecycle_is_explicitly_opt_in)" $ withSystemTempDirectory "petrus-real-gondolin" $ \tmp ->
        withEnvironment [("GITHUB_TOKEN", Just "must-remain-on-host")] $
          realLifecycle tmp node (T.pack sdkText) (T.pack imageText)
    _ ->
      it "runs the real lifecycle (opt-in) (test_real_gondolin_lifecycle_is_explicitly_opt_in)" $
        pendingWith "skipped: set PETRUS_REAL_GONDOLIN_SDK_MODULE and PETRUS_REAL_GONDOLIN_IMAGE (and PETRUS_REAL_GONDOLIN_NODE to a Node >= 23.6) to run against real Gondolin; see PARITY.md"

realLifecycle :: FilePath -> FilePath -> Text -> Text -> IO ()
realLifecycle tmp node sdk image = do
  let root = tmp </> "real"
      realSpec = imageSpec image [capVm, capMicrovm, capPrivateFileTransfer]
      config = (gondolinConfig sdk) {gondolinLeaseTtl = 30, gondolinNode = node}
      source = tmp </> "source"
  createDirectory source
  writeFile (source </> "input.txt") "host input\n"
  archive <- workspaceArchive source
  (env, provider) <- newEnv root config
  lease <- provision env "real-lifecycle" realSpec
  record <- registryOf env "real-lifecycle"
  ( do
      (recreated, recreatedProvider) <- newEnv root config
      gondolinLookup recreated "real-lifecycle" `shouldReturn` Just lease
      attachment <- providerAttach recreatedProvider lease archive "input-digest"
      result <-
        providerExecute recreatedProvider attachment $
          cmdWith
            [ "/bin/sh"
            , "-c"
            , "cat input.txt; test \"${GITHUB_TOKEN-unset}\" = unset; printf guest > output.txt; printf \"#!/bin/sh\\nexit 0\\n\" > mode.sh; chmod 755 mode.sh"
            ]
            (\s -> s {specEnvironment = [("PETRUS_ALLOWED", "yes")]})
      (resultReturncode result, resultStdout result) `shouldBe` (0, "host input\n")
      let restored = tmp </> "restored"
      exported <- providerExport recreatedProvider attachment
      extractWorkspaceArchive exported restored
      readFile (restored </> "output.txt") `shouldReturn` "guest"
      modeOf (restored </> "mode.sh") `shouldReturn` 0o755
      let files = transfer recreatedProvider
      reference <- importPrivateFile files attachment (rightOr (mkPrivateFile "secret" "before"))
      privateResult <-
        providerExecute recreatedProvider attachment $
          cmdWith ["/bin/sh", "-c", "printf after > \"$PRIVATE/secret\""] (\s -> s {specPrivateRoots = [("PRIVATE", reference)]})
      resultReturncode privateResult `shouldBe` 0
      exportPrivateFile files attachment reference `shouldReturn` rightOr (mkPrivateFile "secret" "after")
      (privateCleanupVerified <$> deletePrivateFile files attachment reference) `shouldReturn` True
      (privateCleanupVerified <$> cleanupPrivateFiles files attachment) `shouldReturn` True
      timedOut <-
        providerExecute recreatedProvider attachment $
          cmdWith ["/bin/sh", "-c", "sleep 30; touch /petrus-transfer/should-not-exist"] (\s -> s {specTimeout = Just 0.2})
      (resultTimedOut timedOut, resultSuperseded timedOut) `shouldBe` (True, False)
      doesPathExist (T.unpack (registryWorkspace record) </> "should-not-exist") `shouldReturn` False
    )
    `finally` void (providerDestroy provider lease)
  doesPathExist (T.unpack (registryRuntime record)) `shouldReturn` False
  isEmptyDirectory root `shouldReturn` True

  (supersededEnv, supersededProvider) <- newEnv root config
  supersededLease <- provision supersededEnv "real-superseded" realSpec
  ( do
      checks <- newIORef [True, True, False]
      let current = atomicModifyIORef' checks (\case [] -> ([], False); c : cs -> (cs, c))
      attachment <- providerAttach supersededProvider supersededLease archive "input-digest"
      superseded <-
        providerExecute supersededProvider attachment $
          cmdWith ["/bin/sh", "-c", "sleep 30; touch stale"] (\s -> s {specIsCurrent = Just current})
      (resultSuperseded superseded, resultTimedOut superseded) `shouldBe` (True, False)
    )
    `finally` void (providerDestroy supersededProvider supersededLease)

  (overflowEnv, overflowProvider) <- newEnv root config
  overflowLease <- provision overflowEnv "real-overflow" realSpec
  ( do
      attachment <- providerAttach overflowProvider overflowLease archive "input-digest"
      overflow <-
        providerExecute overflowProvider attachment $
          cmdWith ["/bin/sh", "-c", "yes x | head -c 100000"] (\s -> s {specOutputLimit = 1024})
      resultOutputTruncated overflow `shouldBe` True
      B.length (resultStdout overflow) + B.length (resultStderr overflow) `shouldBe` 1024
    )
    `finally` void (providerDestroy overflowProvider overflowLease)

  (crashEnv, crashProvider) <- newEnv root config
  crashLease <- provision crashEnv "real-crash" realSpec
  crashRecord <- registryOf crashEnv "real-crash"
  killSidecar crashRecord
  lookupState crashEnv "real-crash" `shouldReturn` Just Uncertain
  (reconcileClassification <$> providerReconcile crashProvider "real-crash") `shouldReturn` ReconcileUncertain
  _ <- providerDestroy crashProvider crashLease
  doesPathExist (T.unpack (registryRuntime crashRecord)) `shouldReturn` False
  isEmptyDirectory root `shouldReturn` True

  (ttlEnv, ttlProvider) <- newEnv root config {gondolinLeaseTtl = 0.2}
  ttlLease <- provision ttlEnv "real-ttl" realSpec
  awaitNotReady ttlEnv "real-ttl" 5 0.05
  lookupState ttlEnv "real-ttl" `shouldReturn` Just Uncertain
  _ <- providerDestroy ttlProvider ttlLease
  isEmptyDirectory root `shouldReturn` True
